def color_components(a, ignore=()):
 comps=[]
 for c in np.unique(a):
  if int(c) in ignore: continue
  lab,n=label(a==c)
  for k,sl in enumerate(find_objects(lab),1):
   if sl is None: continue
   mask=lab==k
   # object coordinates
   coords=np.argwhere(mask)
   if not len(coords):continue
   r0,c0=coords.min(axis=0);r1,c1=coords.max(axis=0)
   neigh=set()
   for r,col in coords:
    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
     rr,cc=r+dr,col+dc
     if 0<=rr<a.shape[0] and 0<=cc<a.shape[1] and a[rr,cc]!=c:neigh.add(int(a[rr,cc]))
   comps.append({'color':int(c),'n':len(coords),'box':(int(r0),int(c0),int(r1),int(c1)),'neigh':neigh,'coords':coords})
 return sorted(comps,key=lambda x:(x['box'][0],x['box'][1]))
